import { RegistryController, RegistryInfo } from "approot/global/controllers/registryAsCtrl";
import { PageContext } from "approot/global/services/context";
import { AppLoader } from "approot/global/apploader";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { AlertsService } from "approot/global/providers/uikit.alerts";

export class AchievementsSchoolRegistryController extends RegistryController {
	/*@ngInject*/
	constructor($injector, pageContext: PageContext, $scope: any, $appLoader: AppLoader, $dialogs: DialogsService, $uibModal: any, $alerts: AlertsService, language: any) {
		pageContext.title = "Отчет по личным достижениям одаренных детей";
		pageContext.parent = null;


		const registry: RegistryInfo = {
			url: "/webapi/talents/achievements/registry",
			filtersUrl: "/webapi/talents/achievements/registry/filter",
			buttons: [],
			linkButtons: [],
			extensions: null,
			compactFilters: false
		};

		super($injector, $scope, $appLoader, $dialogs, $uibModal, $alerts, language, registry);
	}
}


