const module = angular.module("irtech.netcity.school.curator",
[
	"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
	"irtech.netcity.common", "ngFileUpload", "ui.tree", "irtech.netcity.ui-components", "irtech.netcity.directive",
	"irtech.netcity.school.portfolio.common", "irtech.netcity.em.events.common", "irtech.netcity.em.talents.common", "irtech.common.fileAttachment"
]);

require("approot/school/portfolio/common/view/portfolioDir.js");
require("approot/em/talents/common/students/awards/listStudentAwardsCmnCtrl.js");
require("approot/em/talents/common/students/portfolio/viewStudentPortfolioCmnCtrl.js");
require("approot/em/events/common/editEvent/editEventCtrl.js");
require("approot/em/events/common/fileAttachment/controller.js");

require("./students/list/listStudentsCtrl.js");
require("./students/portfolio/viewStudentPortfolioCtrl.js");
require("./students/awards/listStudentAwardsCtrl.js");
require("./events/list/listEventsCtrl.js");
require("./events/members/curatorEventMemberListCtr.js");

import { AchievementsSchoolRegistryController } from "./achievements/registry/achievementsListCtrl";

require("approot/global/directives/storageDirective.coffee");

import { EventMemebersComponent } from "../../em/events/common/components/eventMembers.component.ts";

module
	.controller("AchievementsSchoolRegistryController", AchievementsSchoolRegistryController)
	.filter("extension",
		() => {
			return (input) => {
				return input.split(".").pop();
			}
		})
	.component("eventMembersComponent", EventMemebersComponent)
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/events/list",
			{
				templateUrl: "/static/dist/app/school/curator/events/list/template.html",
				controller: "ListCuratorEventsCtrl",
				resolve: {
					isPersonal: () => false
				}
			})
			.when("/events/list/personal",
			{
				templateUrl: "/static/dist/app/school/curator/events/list/template.html",
				controller: "ListCuratorEventsCtrl",
				resolve: {
					isPersonal: () => true
				}
			})
			.when("/events/:eventId/members",
			{
				templateUrl: "/static/dist/app/school/curator/events/members/template.html",
				controller: "CuratorEventsMembersCtrl"
			})
			.when("/students/",
			{
				templateUrl: "/static/dist/app/school/curator/students/list/template.html",
				controller: "ListCuratorStudentsCtrl"
			})
			.when("/students/:studentId/portfolio",
			{
				templateUrl: "/static/dist/app/em/talents/common/students/portfolio/template.html",
				controller: "ViewStudentPortfolioCtrl"
			})
			.when("/students/:studentId/awards",
			{
				templateUrl: "/static/dist/app/em/talents/common/students/awards/template.html",
				controller: "ListStudentAwardsCtrl"
			})
			.when("/achievements",
				{
					templateUrl: "/static/dist/app/global/templates/registryAs.html",
					controller: "AchievementsSchoolRegistryController as ctrl"
				})
			.otherwise({
				templateUrl: "/static/dist/app/school/curator/projects/list/template.html",
				controller: "ListCuratorStudentsCtrl"
			});

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



