"use strict";

angular
	.module("irtech.netcity.school.curator")
	.controller("ViewStudentPortfolioCtrl", ($scope, $http, $routeParams, $location, $appLoader, $controller) => {

		$scope.$parent.page = {
			parent: {
				title: language.Generic.MenuFolders.kFNCuratorTalentStudents,
				href: `students`
			},
			back: { history: true },
			title: "Просмотр портфолио"
		};

		//наследование от базового контроллера
		$controller("ViewStudentPortfolioCmnCtrl", { $scope, $http, $routeParams, $location, $appLoader });

		//просмотр куратором - в режиме только для чтения
		$scope.state.readonly = true;

	});


