"use strict";

angular
	.module("irtech.netcity.em.talents.common")
	.controller("ViewStudentPortfolioCmnCtrl", ($scope, $http, $routeParams, $location, $appLoader, downloadService) => {

		angular.extend($scope, {
			language: language,
			editurl: "",
			data: {
				studentId: $routeParams.studentId,
				portfolio: null
			},
			state: {
				emptyData: false,
				readonly: true
			}
		});

		$http.get(`/webapi/portfolios/personal/`, { params: { userId: $scope.data.studentId} })
			.then((response) => {
				$scope.data.portfolio = response.data;
				if ($scope.data.portfolio == null) {
					$scope.state.emptyData = true;
				}
				$appLoader.hide();
			});


		$scope.openDoc = (url, fileName) => {
			downloadService.downloadFile(url, fileName);
		};
	});



