"use strict";

import EventsReferences from "approot/em/events/common/references.coffee";
import { EventViewModel, EventMemberViewModel } from "approot/em/events/common/model.coffee";
import Selectable from "approot/global/selectable";
import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";

angular
	.module("irtech.netcity.school.curator")
	.controller("CuratorEventsMembersCtrl", ($scope, $http, $q, $alerts, $uibModal, $routeParams, $dialogs, $appLoader) => {

		$scope.$parent.page = {
			parent: {
				title: "План мероприятий",
				href: 'events/list/'
			},
			back: { history: true },
			title: `Список участников мероприятия`
		}

		if (!$routeParams.eventId) {
			return;
		}

		$.extend($scope, {
			language: language,
			data: {
				curatorId: appContext.userId,
				eventId: $routeParams.eventId,
				refs: EventsReferences,
				event: null
			},
			filter: {
				items: {
					viewType:[
						{id: 1, title: 'Все участники'},
						{id: 2, title: 'Свои подопечные'}
					],
					eventMemberTitles: [{id:"All", name: "Все"}].concat(EventsReferences.eventMemberTitles)
				},
				selected: {
					viewType: 1,
					eventMemberTitle: "All"
				}
			},
			state: {
				ready: false
			},
			uiState: {
				startTimeOpened: false
			},
			dateOptions: {
				format: dateUtils.getDateFormat()
			}
		});

		$scope.data.selection = new Selectable();

		let defaultCatch = (response) => $alerts.error(response.data.message || response.data.details);

		const loadCuratorStudents = $http.get(`/webapi/talents/curator/students`)
			.then((response) => {
				$scope.data.curatorStudents = response.data;
			}).catch(defaultCatch);

		const loadEventInfo = $http.get(`/webapi/events/${$scope.data.eventId}`)
			.then((response) => {
				$scope.data.event = new EventViewModel(response.data);
				$http.get(`/webapi/events/files/${$scope.data.event.id}`)
					.then((response) => {
						$scope.data.event.documents = response.data;
				});
			}).catch(defaultCatch);

		const loadMembers = () => {
			return $http.get(`/webapi/events/${$scope.data.eventId}/members`)
				.then((response) => {
					$scope.data.members = _.map(response.data, (dto) => new EventMemberViewModel(dto));
					$scope.filterMembers();
				})
				.catch(defaultCatch);
		};

		$scope.isCuratorStudent = (member) => {
			return _.some($scope.data.curatorStudents, (cs) => { return cs.id === member.user.id });
		}

		$scope.filterMembers = () => {
			$scope.data.viewMembers = _.filter($scope.data.members, (member) => {
				let show = true;
				if ($scope.filter.selected.viewType === 2) {
					show = show && $scope.isCuratorStudent(member);
				}
				if ($scope.filter.selected.eventMemberTitle !== "All") {
					show = show && (member.title && member.title.id === $scope.filter.selected.eventMemberTitle);
				}
				return show;
			});
		}

		$q.all(loadEventInfo, loadMembers(), loadCuratorStudents)
			.then(() => {
				$scope.state.ready = true;
				$appLoader.hide();
			});

		
		//добавить участника
		$scope.addMember = () => {
			let modalInstance = $uibModal.open({
				templateUrl: '/static/dist/app/school/curator/events/members/editMemberTemplate.html',
				controller: EditCuratorEventMemberController,
				controllerAs: "ctrl",
				resolve: {
					eventMemberId: () =>  null,
					user: () => null,
					event: () => $scope.data.event,
					participiationInfo: () => null
				}
			});

			modalInstance.result.then(() => loadMembers());
		}

		//редактировать участника
		$scope.editMember = (member) => {
			let modalInstance = $uibModal.open({
				templateUrl: '/static/dist/app/school/curator/events/members/editMemberTemplate.html',
				controller: EditCuratorEventMemberController,
				controllerAs: "ctrl",
				resolve: {
					eventMemberId: () => member.id,
					user: () => member.user,
					event: () => $scope.data.event,
					participiationInfo: () => member
				}
			});

			modalInstance.result.then(() => loadMembers());
		}

		//удалить участника
		$scope.removeMember = (member) => {
			$dialogs.confirm(language.Generic.SetupSchoolUI.kConfirm, "Вы действительно желаете удалить участника?").result
				.then(() => $http.delete(`/webapi/events/${$scope.data.event.id}/members/${member.id}`).catch(defaultCatch))
				.then(() => {
					$alerts.success("Участник успешно удален");
					$scope.data.members = _.reject($scope.data.members, (item) => item.id === member.id);
					$scope.filterMembers();

					// сброс выбора
					$scope.data.selection.selected = null;
				});
		}
	});

	class EditCuratorEventMemberController extends NetCityModalController{
		/*@ngInject*/
		constructor($scope, $http, $alerts, $dialogs, $longWork, $uibModalInstance, eventMemberId, user, event, participiationInfo, changeTracker){
			super($scope, $uibModalInstance, changeTracker, $dialogs);

			this.$http = $http;
			this.$alerts = $alerts;
			this.$longWork = $longWork;
			this.$uibModalInstance = $uibModalInstance;
			this.eventMemberId = eventMemberId;

			this.mode = {
				create: !eventMemberId,
				edit: eventMemberId > 0
			}
	
			if (this.mode.create) {
				this.header = "Добавить информацию об участии в мероприятии";
			} else {
				this.header = "Редактировать информацию об участии в мероприятии";
			}
	
			const refs = require("approot/em/events/common/references.coffee");
	
			this.language = language;
			this.data = {
				curatorStudents: [],
				refs: refs,
				user: user,
				event: event,
				participiationInfo: participiationInfo
			};
			this.ready = false;
	
			let defaultCatch = (response) => this.$alerts.error(response.data.message || response.data.details);
	
			const loadCuratorStudents = this.$http.get(`/webapi/talents/curator/students`)
				.then((response) => {
					this.data.curatorStudents = response.data;
					this.ready = true;
				}).catch(defaultCatch);
		}

		save() {
			const saveModel = $.extend({id: this.eventMemberId}, { user: this.data.user });

			//обратное преобразование {id, name} -> в id
			for (var property in this.data.participiationInfo) {
				if (this.data.participiationInfo.hasOwnProperty(property)) {
					let propValue = this.data.participiationInfo[property];
					if (saveModel.hasOwnProperty(property)) {
						continue;
					}
					if (propValue === null || typeof (propValue) === "undefined") {
						continue;
					}

					if (typeof(propValue.id) != "undefined" && typeof(propValue.name) != "undefined" &&
						_.filter(Object.keys(propValue), (prop) => prop.charAt(0) !== '$').length === 2) {

						saveModel[property] = propValue.id;
					} else {
						saveModel[property] = propValue;
					}
				}
			}

			const url = `/webapi/events/${this.data.event.id}/members`;
			const errHandler = (response) => {
				this.$alerts.error(response.data.message || response.data.details);
			}

			if (this.mode.edit) {
				this.$http.put(url, saveModel)
					.then((response) => this.$uibModalInstance.close(response.data))
					.catch(errHandler);
			} else {
				this.$http.post(url, saveModel, { params: { curatorId: appContext.userId } })
					.then((response) => this.$uibModalInstance.close(response.data))
					.catch(errHandler);
			}
		}

		cancel(){
			this.$uibModalInstance.dismiss('cancel');
		};
	}
;


