"use strict";

import * as FileSaver from "webroot/vendor/components/file-saver/FileSaver.js";

angular.module("irtech.common.fileAttachment", ["ngFileUpload", "uikit.alerts", "uikit.dialogs"])
	.controller("AddFileAttachmentCtrl", ($scope, $http, $alerts, $uibModalInstance, $longWork, Upload, url, doc, lazy, $controller, $dialogs, changeTracker) => {
		$scope.editMode = doc.id > 0;
		$scope.header = $scope.editMode ? "Редактирование документа" : "Создание документа";

		angular.extend($scope, {
			language: language,
			data: {
				url: url,
				doc: doc
			},
			lazy
		});
		$scope.data.doc.fileName = doc.originalFileName;

		$scope.$watch("data.doc.file", (file) => {
			if (file) {
				$scope.data.doc.fileName = file.name;
				// Получаем размер файла в MiB (мегабайт, по МЭК)
				const fileSize = $scope.data.doc.file.size >> 20;
				$scope.fileSize = fileSize;
				if (fileSize > 10) {
					$alerts.error("Размер загружаемого файла не должен превышать 10 МБ");
				}
			}
		});

		const baseSave = (url, method, document) => {
			return Upload.upload({
				url: url,
				method: method,
				data: document
			});
		}

		const save = (url, method) => {
			let document = {
				file: $scope.data.doc.file,
				info: JSON.stringify({
					Id: doc.id < 0 ? 0 : doc.id,
					Name: $scope.data.doc.name,
					Description: $scope.data.doc.description
				})
			}
			return baseSave(url, method, document);
		};

		const method = $scope.editMode ? "PUT" : "POST";

		const lazyFileLoad = () => {
			const getProxyUrl = (fileData) => {
				const blob = new Blob([fileData], {type: "octet/stream"});
				return window.URL.createObjectURL(blob);
			}

			const download = (fileData, name) => {
				const blob = new Blob([fileData], {type: "octet/stream"});
				return () => FileSaver.saveAs(blob, name);
			}

			const getProxyFile = (id, document) => {
				if(doc.isProxy){
					document.file = document.file || doc && doc.data && doc.data.file
				}
				return {
					id: id || 0,
					name: document.name,
					description: document.description,
					originalFileName: document.fileName,
					data: {
						file: document.file,
						info: JSON.stringify({
							Id: id <= 0 ? 0 : id,
							Name: document.name,
							Description: document.description
						})
					},
					download: download(document.file, document.fileName),
					proxyUrl: getProxyUrl(document.file),
					isProxy: true
				}
			}
			let proxyFile = getProxyFile(doc.id, $scope.data.doc);

			$uibModalInstance.close(proxyFile);
		}

		$scope.save = () => {
			if (!$scope.docForm.$valid || $scope.fileSize > 10) {
				$scope.docForm.$displayErrors = true;
				return;
			}

			if (lazy) return lazyFileLoad();

			save($scope.data.url, method)
				.then(
					(response) => {
						$alerts.success("Документ успешно сохранен");
						$uibModalInstance.close(response.data);
						return response.data;
					},
					(response) => {
						$alerts.error(response.data.message, response.data.details);
					}
				);
		}

		$scope.cancel = () => {
			$uibModalInstance.dismiss("cancel");
		}
		$controller("NetCityModalController", { $scope, $dialogs, $uibModalInstance, changeTracker });
	});


