"use strict";

import { EventViewModel } from "approot/em/events/common/model.coffee";
import references from "approot/em/events/common/references.coffee";
import SearchSource from "approot/global/searchSource.js";
import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";

angular.module("irtech.netcity.em.events.common", []);

export class EditUserEventController extends NetCityModalController {
	/*@ngInject*/
	constructor($scope, $http, $alerts, $dialogs, $uibModalInstance, changeTracker, eventMemberId, user, event, participiationInfo){
		super($scope, $uibModalInstance, changeTracker, $dialogs);

		this.$http = $http;
		this.$alerts = $alerts;
		this.$uibModalInstance = $uibModalInstance;

		this.eventMemberId = eventMemberId;
		this.mode = {
			selectUser: user === null || !user.id,
			selectEvent: event === null || !event.id,
			create: !eventMemberId,
			edit: eventMemberId > 0
		}

		this.errHandler = (response) => {
			this.$alerts.error(response.data.message || response.data.details);
		}

		if (this.mode.create) {
			this.header = "Добавить информацию об участии в мероприятии";
		} else {
			this.header = "Редактировать информацию об участии в мероприятии";
		}

		
		this.language = language;
		this.data = {
			search: {},
			yearId: new Date().getFullYear() - 2000,
			refs: references,
			events: [],
			user: user || {},
			event: event || null,
			participiationInfo: participiationInfo
		};
		this.state = {
			edit: participiationInfo !== null,
			loadEvents: false,
			noEvents: false
		};
		this.dateOptions = {
			format: dateUtils.getDateFormat()
		};
		this.ready = true;

		this.$http.get("/webapi/references/years")
			.then((response) => {
				this.data.refs.years = response.data;
			})
			.catch(this.errHandler);

		if (this.mode.create) {
			//при создании контроллируем взаимосвязанные фильтры: год + мероприятие и школа + участник
			$scope.$watch(() => this.data.yearId, (newVal, oldVal) => {
				this.getEvents(newVal);

				if (!this.data.event || !this.data.event.id) {
					return;
				}

				if (!oldVal || !newVal) {
					return;
				}

				if (newVal == oldVal) {
					return;
				}

				//при переключении года сбрасываем информацию о найденных мероприятиях
				//this.data.search.events.items = [];
				this.data.event = null;
			});

			if (this.mode.selectUser) {
				$scope.$watch(() => this.data.schoolId, () => { this.data.user = null; });
			}
		}

		let searchSettings = {};
		if (this.mode.selectEvent) {
			//требуется поиск мероприятий
			angular.extend(searchSettings,
			{
				events: {
					url: "/webapi/events/search",
					map: (item) => new EventViewModel(item),
					params: {
						yearId: () => this.data.yearId,
						eventType: "awardEvents"
					}
				}
			});
		}

		if (this.mode.selectUser) {
			//требуется поиск организаций и пользователей
			angular.extend(searchSettings,
			{
				schools: {
					url: "/webapi/schools/search",
					params: {
						take: 20
					}
				},
				users: {
					url: "/webapi/users/search",
					params: {
						schoolId: () => this.data.schoolId,
						globalYearId: () => this.data.event._globalYearId,
						take: 50,
						contains: true
					}
				}
			});

			//при создании контроллируем взаимосвязанные фильтры: год + мероприятие и школа + участник
			$scope.$watch(() => this.data.schoolId, () => {
				//при переключении ОО сбрасываем информацию о найденных пользователях
				this.data.search.users.items = [];
				this.data.user = null;
			});

		}

		this.data.search = new SearchSource(searchSettings, this.$http);

	}

	getEventGroup(eventVM) {
		if (eventVM.awardEventType) {
			return eventVM.awardEventType.name;
		}
		return "";
	}

	getEvents(yearId){
		this.state.loadEvents = true;
		this.data.events = [{ name: 'Поиск...' }];

		return this.$http.get("/webapi/awardEvents/available", { params: { yearId } })
			.then((response) => {
				this.data.events = _.map(response.data, (item) => new EventViewModel(item));
				this.state.loadEvents = false;
				this.state.noEvents = this.data.events.length === 0;
			}, this.errHandler);
	}

	save() {
		const saveModel = $.extend({id: this.eventMemberId}, { user: this.data.user });

		//обратное преобразование {id, name} -> в id
		for (var property in this.data.participiationInfo) {
			if (this.data.participiationInfo.hasOwnProperty(property)) {
				let propValue = this.data.participiationInfo[property];
				if (saveModel.hasOwnProperty(property)) {
					continue;
				}
				if (propValue === null || typeof (propValue) === "undefined") {
					continue;
				}

				if (typeof(propValue.id) != "undefined" && typeof(propValue.name) != "undefined" &&
					_.filter(Object.keys(propValue), (prop) => prop.charAt(0) !== '$').length === 2) {

					saveModel[property] = propValue.id;
				} else {
					saveModel[property] = propValue;
				}
			}
		}

		const url = `/webapi/events/${this.data.event.id}/members`;

		let request, msg;

		if (this.state.edit) {
			msg = "Данные об участии успешно изменены";
			request = this.$http.put(url, saveModel);
		} else {
			msg = "Данные об участии успешно добавлены";
			request = this.$http.post(url, saveModel);
		}

		request.then((response) => {
			this.$alerts.success(msg);
			this.$uibModalInstance.close(response.data);
			},
			this.errHandler);
	}

	cancel() {
		this.$uibModalInstance.dismiss('cancel');
	}
}	


