"use strict";

import EventsReferences from "approot/em/events/common/references.coffee";
import { EventViewModel } from "approot/em/events/common/model.coffee";
import Selectable from "approot/global/selectable";

angular
	.module("irtech.netcity.school.curator")
	.controller("ListCuratorEventsCtrl", ($scope, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $uibModal, $location, isPersonal) => {

		$scope.isPersonalPlan = isPersonal;

		$scope.$parent.page = {
			title: isPersonal ? language.Generic.MenuFolders.kFNCuratorPersonalPlan : language.Generic.MenuFolders.kFNCuratorCommonPlan
		}

		//todo. добавить в appContext текущий globalyearId
		const globalYearId = new Date().getFullYear() - 2000;

		$.extend($scope, {
			language: language,
			data: {
				events: [],
				yearId: globalYearId,
				eventLevel: null,
				awardEventType: null,
				eventStatus: "All",
				refs: EventsReferences
			},
			state: {
				dataReady: false,
				emptyData: false,
				viewReady: false
			}
		});

		$scope.data.selection = new Selectable();

		const yearsReady = $http.get("/webapi/references/years").then((response) => {
			$scope.data.years = response.data;
			if (!$scope.data.yearId) {
				$scope.data.yearId = _.first($scope.data.years).id;
			}
		});

		//просмотр участников мероприятия
		$scope.viewEventMembers = (event) => {
			$location.path(`/events/${event.id}/members`);
		}

		//создание мероприятия
		$scope.add = () => {
			const modalInstance = $uibModal.open({
				templateUrl: '/static/dist/app/em/events/common/editEvent/template.html',
				controller: 'EditEventCtrl',
				size: "lg",
				resolve: {
					model: () => {
						return {
							event: {
								id: 0,
								organization: {},
								startTime: new Date(),
								globalYearId: $scope.data.yearId,
								curatorId: appContext.userId
							},
							educYears: $scope.data.years,
							refs: $scope.data.refs
						}
					}
				}
			});
			modalInstance.result.then(() => $scope.load());
		};

		//создание мероприятия
		$scope.edit = (event) => {
			const modalInstance = $uibModal.open({
				templateUrl: '/static/dist/app/em/events/common/editEvent/template.html',
				controller: 'EditEventCtrl',
				size: "lg",
				resolve: {
					model: () => {
						return {
							event: event.dto,
							refs: $scope.data.refs,
							educYears: $scope.data.years
						}
					}
				}
			});
			modalInstance.result.then(() => $scope.load());
		};

		$scope.restore = (event) => {
			$.show.error("Не реализовано");
		}

		//удаление мероприятия
		$scope.remove = (event) => {

			$dialogs.confirm("В случае продолжения будут удалено выбранное мероприятие а также данные об участниках данного мероприятия.\nВы желаете продолжить?")
				.then(() => $http.delete("/webapi/events/", { params: { eventId: event.id } }))
				.then(() => {
					$alerts.success("Мероприятие успешно удалено");
					$scope.load();
				});
		}

		$scope.isSelfPlanEvent = (selectedEvent) => {
			return selectedEvent.personalEvent;
		}

		$scope.load = () => {
			$scope.state.dataReady = false;
			const params = {
				yearId: $scope.data.yearId,
				level: $scope.data.eventLevel,
				status: $scope.data.eventStatus,
				awardEventType: $scope.data.awardEventType,
				
			};

			if ($scope.isPersonalPlan) {
				params.curatorId = appContext.userId;
			}

			$http.get("/webapi/events/awardevents/", { params }).then((response) => {
				$scope.data.events = _.map(response.data, (eventDto) => new EventViewModel(eventDto));

				$scope.state.dataReady = true;
				$scope.state.viewReady = true;

				$scope.state.emptyData = response.data.length === 0;
				$appLoader.hide();
			});
		}

		yearsReady.then(() => {
			$scope.load();
		});
	});



