"use strict";

import { EventViewModel, EventResultsViewModel } from "approot/em/events/common/model.coffee";
import * as Rights from "approot/global/references/rights.js";
import { EditUserEventController } from "approot/em/events/common/eventMember/editEventMemberCtrl.js";

angular
	.module("irtech.netcity.em.talents.common", [])
	.controller("ListStudentAwardsCmnCtrl", ($scope, $http, $routeParams, $location, $appLoader, $uibModal, $alerts, $dialogs) => {
		angular.extend($scope, {
			language: language,
			data: {
				studentId: $routeParams.studentId,
				competitions: []
			},
			state: {
				accessToMembers: _.contains(context.rights, Rights.arEMEventsMembersView) || _.contains(context.rights, Rights.arEMEventsMembersEdit)
			},
			alerts:$alerts

		});

		const defaultErrHandler = (response) => $alerts.error(response.data.message, response.data.details);

		//маппинг и группировка данных об участии
		const mapEvents = (dtos) => {
			return _.chain(dtos)
				.map((dto) => {
					dto.eventInfo = new EventViewModel(dto.eventInfo);
					dto.participiationInfo = new EventResultsViewModel(dto.participiationInfo);
					return dto;
				})
				.groupBy((dto) => dto.eventInfo.startTime.getFullYear())
				.map((awards, year) => {
					return {
						year: year,
						awards: awards
					};
				})
				.sortBy((yearAwards) => { return -yearAwards.year })
				.value();
		};

		//добавить информацию об участии в мероприятии
		$scope.add = () => {
			const modal = $uibModal.open({
				templateUrl: "/static/dist/app/em/events/common/eventMember/template.html",
				controller: EditUserEventController,
				controllerAs: "ctrl",
				size: "lg",
				resolve: {
					eventMemberId: () => null,
					user: () => { return { id: $scope.data.studentId } },
					event: () => null,
					participiationInfo: () => null
				}
			});

			modal.result.then(() => $scope.load());
		}

		//редактировать информацию об участии в мероприятии
		$scope.edit = (award) => {
			const editAward = angular.copy(award);
			const modal = $uibModal.open({
				templateUrl: "/static/dist/app/em/events/common/eventMember/template.html",
				controller: EditUserEventController,
				controllerAs: "ctrl",
				size: "lg",
				resolve: {
					eventMemberId: () => editAward.eventMemberId,
					user: () => { return { id: $scope.data.studentId } },
					event: () => editAward.eventInfo,
					participiationInfo: () => editAward.participiationInfo
				}
			});

			modal.result.then(() => $scope.load());
		}

		//удаление информации об участии в мероприятии
		$scope.remove = (award) => {
			$dialogs.confirm("Вы действительно желаете удалить информацию об участии в мероприятии?")
				.then(() => $http.delete(`/webapi/users/${$scope.data.studentId}/events`, { params: { eventMemberId: award.eventMemberId } }).catch(defaultErrHandler))
				.then(() => { $scope.load(); })
				.then(() => $scope.alerts.success(`Данные об участии успешно удалены`));
				
		};

		$scope.load = () => {
			$http.get(`/webapi/users/${$scope.data.studentId}/events`)
				.then((response) => {
					$scope.data.competitions = mapEvents(response.data);
					$appLoader.hide();
				})
				.catch(defaultErrHandler);
		}

		$scope.load();
	});



