"use strict";

import Selectable from "approot/global/selectable";

angular
	.module("irtech.netcity.school.curator")
	.controller("ListCuratorStudentsCtrl", ($scope, $http, $q, $alerts, $dialogs, $appLoader, $location) => {

		$scope.$parent.page = {
			title: language.Generic.MenuFolders.kFNCuratorTalentStudents
		}

		$.extend($scope, {
			language: language,
			filter: {
				items: {
					schools: []
				},
				selected: {
					schoolId: -1
				}
			},
			data: {
				students: []
			},
			state: {
				dataReady: false
			}
		});

		const loadStudents = $http.get(`/webapi/talents/curator/students`)
			.then((response) => {
				$scope.data.students = response.data;
			});

		$q.all([loadStudents])
			.then(() => {
				const schoolIds = _.chain($scope.data.students)
					.filter((st) => st.education && st.education.schoolId)
					.map(	(st) => st.education.schoolId )
					.value();
				if (schoolIds.length) {
					return $http.get(`/webapi/schools/short`, { params: { id: schoolIds, withCityName: true } });
				} else {
					return { data: [] };
				}
			})
			.then((response) => {
				$scope.filter.items.schools = response.data;
				$scope.filter.items.schools.unshift({id: -1, name: "Все"});
				const schoolsIdx = _.indexBy(response.data, "id");

				$scope.data.students = _.map($scope.data.students, (studentDto) => {
					if (studentDto.education && studentDto.education.schoolId > 0) {
						studentDto.education.school = schoolsIdx[studentDto.education.schoolId];
					}
					studentDto.birthDate = dateUtils.date2str(new Date(studentDto.birthDate));
					
					if (studentDto.talentDirection) {
						studentDto.viewDirections = studentDto.talentDirection.map(x => x.name).toString();
					}
					
					return studentDto;
				});

				$scope.filterViewStudents();

				$appLoader.hide();
				$scope.state.dataReady = true;

			});


		$scope.filterViewStudents = () => {
			const schoolId = $scope.filter.selected.schoolId;
			$scope.data.viewStudents = _.filter($scope.data.students,
				(student) => schoolId < 0 || (student.education && student.education.school.id === schoolId) );
		}

		$scope.data.selection = new Selectable();

		$scope.viewAwards = () => {
			$location.path(`/students/${$scope.data.selection.selected.id}/awards`);
		}

		$scope.viewPortfolio = () => {
			$location.path(`/students/${$scope.data.selection.selected.id}/portfolio`);
		}
	});



