"use strict";

angular
	.module("irtech.netcity.school.curator")
	.controller("ListStudentAwardsCtrl", ($scope, $http, $routeParams, $location, $appLoader, $uibModal, $controller) => {

		$scope.$parent.page = {
			parent: {
				title: language.Generic.MenuFolders.kFNCuratorTalentStudents,
				href: `students`
			},
			back: { history: true },
			title: "Личные достижения"
		}

		$scope.viewEvent = (eventId) => {
			$location.path(`/events/${eventId}/members`);
		};

		//наследование от базового контроллера
		$controller("ListStudentAwardsCmnCtrl", { $scope, $http, $routeParams, $location, $appLoader });

		$scope.state.accessToMembers = true;
	});


